// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Nitel araştırma yöntemleri (kolay).
const ozResearch8Kolay = <(String, String, List<String>, String)>[
  ('Nitel araştırmalarda verinin toplandığı yer genellikle nasıl nitelenir?', 'Olayların kendiliğinden yaşandığı doğal ortam', ['Değişkenlerin sıkıca denetlendiği laboratuvar ortamı', 'Araştırmacının kurduğu yapay deney düzeneği', 'Yalnızca çevrimiçi anket platformları'], 'Nitel araştırma insanları kendi yaşam ortamlarında, olayların doğal akışı içinde inceler. Laboratuvar denetimi nicel deneysel çalışmaların özelliğidir.'),
  ('Nitel araştırmalarda "araştırmacının kendisinin temel veri toplama aracı olması" ne anlama gelir?', 'Veriyi bizzat gözleyen, soran ve yorumlayan kişinin araştırmacı olması', ['Araştırmacının yalnızca hazır ölçekleri dağıtıp sonra geri toplaması', 'Verinin tümüyle yazılım tarafından otomatik çözümlenmesi', 'Araştırmacının kendi görüşlerini veri yerine koyması'], 'Nitel çalışmada ölçek ya da test yerine araştırmacı görüşme yapar, gözlem yapar ve anlam çıkarır. Bu nedenle araştırmacının becerisi ve duyarlılığı verinin niteliğini doğrudan etkiler.'),
  ('Nitel araştırmalarda desenin "esnek" ya da "ortaya çıkan" (emergent) olması neyi ifade eder?', 'Sorular ve veri toplama adımlarının alandan gelen bilgilere göre uyarlanabilmesi', ['Araştırmanın hiçbir planı olmadan rastgele yürütülmesi', 'Örneklem büyüklüğünün baştan güç analiziyle istatistiksel olarak sabitlenmesi', 'Bulguların araştırmacının dilediği gibi değiştirilebilmesi'], 'Ortaya çıkan desende araştırmacı bir planla başlar ama sahada öğrendiklerine göre soruları, katılımcıları ya da yöntemleri düzenleyebilir. Bu, plansızlık değil, verinin yönlendirdiği bir uyarlamadır.'),
  ('Nitel araştırmanın "bütüncül" (holistik) bakış açısı aşağıdakilerden hangisiyle en iyi açıklanır?', 'Olgunun bağlamı ve parçaları arasındaki ilişkilerle birlikte ele alınması', ['Olgunun tek bir değişkene indirgenerek ölçülmesi', 'Yalnızca en sık görülen yanıtların raporlanması', 'Farklı bağlamların göz ardı edilerek tüm yanıtların ortalamasının alınması'], 'Bütüncül yaklaşım, bir durumu ya da deneyimi onu çevreleyen toplumsal, tarihsel ve kişisel bağlamla birlikte anlamaya çalışır.'),
  ('Aşağıdaki araştırma amaçlarından hangisi en çok nitel bir yaklaşım gerektirir?', 'Göçmen öğrencilerin yeni okullarına uyum sürecini nasıl anlamlandırdığını keşfetmek', ['Türkiye\'deki ortaokullarda ortalama sınıf mevcudunu hesaplamak', 'Bir ilacın tansiyonu kaç birim düşürdüğünü ölçmek', 'Bir ildeki kayıtlı seçmenlerin yüzde kaçının sandığa gidip oy kullandığını bulmak'], 'Anlamlandırma ve süreç keşfi katılımcıların bakışını derinlemesine anlamayı gerektirir. Diğer seçenekler sayı, ortalama ya da oran istediği için nicel yöntemlere uygundur.'),
  ('Nitel araştırmalarda katılımcı sayısının genellikle küçük tutulmasının asıl gerekçesi nedir?', 'Amaç temsil etmekten çok az sayıda durumu derinlemesine anlamaktır', ['Nitel araştırmalar istatistiksel güç hesabıyla küçük örneklem gerektirir', 'Küçük örneklem bulguların tüm nüfusa genellenmesini kolaylaştırır', 'Etik kurullar nitel araştırmada en çok on kişiye izin verir'], 'Nitel çalışmalar derinliği genişliğe tercih eder; her katılımcıdan zengin veri toplamak ve çözümlemek zaman aldığından örneklem küçük tutulur.'),
  ('Nicel araştırmada araştırmacının mesafeli ve nesnel kalmaya çalışmasına karşın nitel araştırmada araştırmacı-katılımcı ilişkisi genellikle nasıl görülür?', 'Anlamın birlikte kurulduğu, etkileşimli bir ilişki', ['Araştırmacının hiçbir biçimde katılımcıyla konuşmadığı bir ilişki', 'Katılımcının yalnızca deney nesnesi sayıldığı bir ilişki', 'Araştırmacının sonuçları önceden belirlediği bir ilişki'], 'Yorumlayıcı geleneğe göre bilgi, araştırmacı ile katılımcının etkileşimi içinde oluşur. Bu nedenle nitel araştırmacı ilişkiyi yok saymaz, onu düşünümsel biçimde yönetir.'),
  ('Gerçekliğin tek ve nesnel olmadığını, insanların onu toplumsal etkileşim içinde farklı biçimlerde kurduğunu savunan ve nitel araştırmanın büyük bölümüne temel oluşturan paradigma hangisidir?', 'Yapılandırmacılık', ['Pozitivizm', 'Davranışçılık', 'Mantıksal atomculuk'], 'Yapılandırmacı (yorumlayıcı) paradigma çoklu gerçeklikleri kabul eder ve bilginin bağlam içinde kurulduğunu savunur. Pozitivizm ise tek ve ölçülebilir bir gerçeklik varsayar.'),
  ('Bilimsel bilginin yalnızca gözlemlenebilir ve ölçülebilir olgulardan elde edilebileceğini savunan ve nicel araştırma geleneğinin felsefi dayanağı sayılan görüş hangisidir?', 'Pozitivizm', ['Hermenötik', 'Olgubilim', 'Yapısökümcülük'], 'Auguste Comte\'la ilişkilendirilen pozitivizm, doğa bilimlerinin yöntemlerini toplum bilimlerine de uygular ve ölçülebilir olgulara odaklanır.'),
  ('Araştırmanın yalnızca anlamayı değil toplumsal eşitsizlikleri görünür kılıp değiştirmeyi de amaçlaması gerektiğini savunan paradigma hangisidir?', 'Eleştirel paradigma', ['Pozitivist paradigma', 'Postpozitivist paradigma', 'İşlevselci paradigma'], 'Eleştirel kuram geleneğine dayanan paradigma güç ilişkilerini sorgular ve araştırmayı özgürleştirici bir eylem olarak görür; feminist ve katılımcı araştırmalar bu çizgiden beslenir.'),
  ('Bir paradigmanın "ontolojik" varsayımı hangi soruya yanıt verir?', 'Gerçekliğin doğası nedir?', ['Bilgiyi nasıl edinebiliriz?', 'Hangi istatistik testini kullanmalıyız?', 'Araştırmanın bütçesi ne kadar olmalı?'], 'Ontoloji varlığın ve gerçekliğin doğasıyla ilgilidir. "Bilgiyi nasıl edinebiliriz?" sorusu ise epistemolojinin alanına girer.'),
  ('Çok sayıda birey üzerinden genel yasalar ve düzenlilikler bulmayı amaçlayan yaklaşım hangisidir?', 'Nomotetik yaklaşım', ['İdiografik yaklaşım', 'Hermenötik yaklaşım', 'Biyografik yaklaşım'], 'Nomotetik yaklaşım genellenebilir yasalar arar; büyük örneklemli nicel araştırmalar bu yaklaşımı izler.'),
  ('Nitel araştırmada verilerden yola çıkarak kavram ve örüntülere ulaşılmasına ne tür akıl yürütme denir?', 'Tümevarım', ['Tümdengelim', 'Kıyas', 'Analoji'], 'Nitel çözümleme çoğunlukla tümevarımsaldır: tek tek veri parçalarından kodlara, kodlardan temalara ve kavramlara doğru ilerlenir.'),
  ('Olgubilimsel bir çalışmada temel veri toplama aracı genellikle hangisidir?', 'Deneyimi yaşamış kişilerle derinlemesine görüşme', ['Geniş örneklemli kapalı uçlu anket formu', 'Laboratuvarda tepki süresi ölçümü', 'Resmî istatistiklerin taranması'], 'Olgubilim yaşanmış deneyimin anlamını araştırdığından, olguyu doğrudan yaşamış kişilerle yapılan derinlemesine görüşmeler temel veri kaynağıdır.'),
  ('Olgubilimsel bir çalışmada katılımcı seçiminde vazgeçilmez ölçüt hangisidir?', 'Katılımcıların incelenen olguyu bizzat yaşamış olması', ['Katılımcıların nüfusu oranlı biçimde temsil etmesi', 'Katılımcıların birbirini hiç tanımaması', 'Katılımcıların araştırma yöntemleri eğitimi almış olması'], 'Olgubilim bir deneyimin özünü yaşayanların gözünden anlamaya çalışır. Bu nedenle ölçüt, olguyu deneyimlemiş olmaktır; temsil edicilik aranmaz.'),
  ('Gömülü kuram çalışmasında araştırmacının kodlama sırasında aklına gelen fikirleri, kategoriler arası ilişkileri ve soruları yazdığı kısa metinlere ne ad verilir?', 'Analitik not', ['Görüşme formu', 'Onam belgesi ve bilgilendirme metni', 'Transkript'], 'Analitik notlar (memolar) kuram geliştirmenin ara ürünleridir; kodlardan kategorilere, kategorilerden kurama geçişi belgeleyip düşünmeyi ilerletir.'),
  ('Araştırmacının kendi kişisel deneyimini sistematik biçimde inceleyerek bu deneyimi daha geniş bir kültürel bağlamla ilişkilendirdiği nitel yaklaşıma ne ad verilir?', 'Otoetnografi', ['Netnografi', 'Katılımsız yapılandırılmış gözlem çalışması', 'Delphi tekniği'], 'Otoetnografide araştırmacı hem araştıran hem de araştırılandır; kendi yaşantısını kültürel anlamlarla bağlantılı olarak yazar.'),
  ('Etnografik çalışmada bir kuruma ya da topluluğa erişim için izin verme yetkisi olan kişiye (ör. okul müdürü, köy muhtarı) ne ad verilir?', 'Kapı bekçisi', ['Raportör', 'Moderatör ve not tutucu', 'Yerli araştırmacı'], 'Kapı bekçisi (gatekeeper) alana girişi onaylayan ya da engelleyen kişidir. Bu kişi araştırmacıyı diğer üyelerle tanıştıran kilit bilgi vericiyle aynı olmak zorunda değildir.'),
  ('Yabancı bir kültürde alan çalışmasına başlayan bir araştırmacının alışık olmadığı normlar karşısında yaşadığı şaşkınlık, kaygı ve yönelim kaybına ne ad verilir?', 'Kültür şoku', ['Yerlileşme', 'Gözlemci kayması', 'Grup düşüncesi'], 'Kültür şoku alana girişin ilk evrelerinde sık görülür. Etnograflar bu deneyimi de alan notlarına kaydederek kendi varsayımlarını fark etmek için kullanır.'),
  ('Etnografların "tanıdık olanı yabancılaştırmak" ilkesi en çok hangi durumda önem kazanır?', 'Araştırmacının kendi kültürünü ya da yakından bildiği bir ortamı incelemesinde', ['Araştırmacının hiç bilmediği uzak bir topluluğa ilk kez gitmesinde', 'Araştırmacının yalnızca hazır istatistikleri incelemesinde', 'Laboratuvarda bir deney yürütülmesinde'], 'Tanıdık ortamda olağan sayılan uygulamalar gözden kaçabilir. Bu ilke, araştırmacının alışılmış olanı ilk kez görüyormuş gibi sorgulamasını önerir.'),
  ('Etnografik bir çalışmada araştırmacının alan notları, görüşmeler, belgeler ve fotoğraflar gibi farklı veri türlerini bir arada kullanması en çok hangi amaca hizmet eder?', 'Kültürel örüntüyü farklı açılardan zengin biçimde betimlemek', ['Çalışmayı daha kısa sürede bitirmek', 'Katılımcı sayısını en aza indirmek', 'Yorum yapma gereğini ortadan kaldırmak'], 'Etnografi bütüncül bir betimleme amaçlar; çoklu veri türleri kültürün farklı yönlerini görünür kılar ve yorumları güçlendirir.'),
  ('Stake\'in sınıflamasında birden fazla durumun aynı konuyu anlamak için birlikte incelendiği türe ne ad verilir?', 'Kolektif durum çalışması', ['İçsel durum çalışması', 'Bütüncül tek durum çalışması', 'Boylamsal tek durum çalışması'], 'Kolektif (collective) durum çalışması, birkaç araçsal durumun bir arada incelenmesidir; Yin\'in çoklu durum desenine karşılık gelir.'),
  ('Bir ya da birkaç bireyin yaşantılarını onların anlattığı öyküler aracılığıyla toplayıp kronolojik ve anlamlı bir bütün halinde yeniden düzenleyen nitel desen hangisidir?', 'Anlatı araştırması', ['Gömülü kuram', 'Nitel içerik analizi', 'Odak grup çalışması ve tartışma'], 'Anlatı araştırması bireysel öykülere odaklanır; araştırmacı öyküleri toplar, çözümler ve çoğu zaman katılımcıyla birlikte yeniden öyküler.'),
  ('Bir kişinin yaşamının araştırmacı tarafından, o kişiyle görüşme yapmanın yanı sıra belgeler ve başkalarının anlatımlarıyla birlikte yazılmasına ne ad verilir?', 'Biyografik çalışma', ['Otobiyografi', 'Kurumsal etnografi', 'Delphi çalışması'], 'Biyografik çalışmada yaşamı araştırmacı yazar; otobiyografide ise kişi kendi yaşamını kendisi yazar.'),
  ('Biyografik araştırmalarda yaşam akışını yönünü değiştiren olaylara (ör. göç, bir yakının ölümü, meslek değişikliği) ne ad verilir?', 'Dönüm noktaları', ['Doygunluk noktaları', 'Kontrol değişkenleri', 'Ölçüm noktaları'], 'Biyografik çalışmalar dönüm noktalarına (epiphanies, turning points) özel önem verir; bu anlar kişinin kimliğini ve anlam dünyasını yeniden biçimlendirir.'),
  ('Dilin yalnızca bir şeyi betimlemekle kalmayıp toplumsal gerçekliği de kurduğu varsayımıyla konuşma ve metinlerin nasıl anlam ürettiğini inceleyen nitel yaklaşıma ne ad verilir?', 'Söylem analizi', ['Sıklık sayımına dayalı nicel içerik analizi', 'Kapalı uçlu anket çözümlemesi', 'Deneysel desen'], 'Söylem analizi dili bir eylem ve toplumsal kurgu aracı olarak görür; ne söylendiğinden çok nasıl ve hangi amaçla söylendiğiyle ilgilenir.'),
  ('Konuşma çözümlemesinde konuşmacıların söz hakkını nasıl el değiştirdiğini, kimin ne zaman konuşacağının nasıl belirlendiğini inceleyen konuya ne ad verilir?', 'Sıra alma', ['Kuramsal örnekleme', 'Tümevarımsal kodlama', 'Yataylaştırma'], 'Sacks, Schegloff ve Jefferson\'ın 1974 tarihli makalesi sıra alma düzeninin kurallarını tanımlamıştır; söz kesmeler ve örtüşmeler bu çerçevede incelenir.'),
  ('Betimsel analizde verilerin sunumunda katılımcıların görüşlerini yansıtmak için en sık başvurulan yol hangisidir?', 'Doğrudan alıntılara yer vermek', ['Yalnızca ortalama ve standart sapma tablosu vermek', 'Katılımcıların adlarını ve adreslerini listelemek', 'Verileri hiç sunmadan yalnızca sonucu yazmak'], 'Betimsel analizde temalar özetlenirken bulguların katılımcının sesiyle desteklenmesi için doğrudan alıntılar sıkça kullanılır.'),
  ('Braun ve Clarke\'ın tematik analiz aşamalarında, verilerin tanınmasından hemen sonra gelen ve verinin ilginç özelliklerinin sistemli biçimde etiketlendiği aşama hangisidir?', 'Başlangıç kodlarının oluşturulması', ['Temaların adlandırılması', 'Raporun yazılması', 'Temaların gözden geçirilip gerekirse birleştirilmesi'], 'Braun ve Clarke\'ın altı aşaması: verilerle tanışma, başlangıç kodlarının oluşturulması, temaların aranması, temaların gözden geçirilmesi, temaların tanımlanıp adlandırılması ve raporun yazılmasıdır.'),
  ('Braun ve Clarke\'ın tematik analizinin son aşaması hangisidir?', 'Raporun yazılması', ['Başlangıç kodlarının oluşturulması', 'Verilerle tanışma', 'Temaların aranması'], 'Rapor yazma, canlı alıntılar seçerek temaları araştırma sorusuyla ve alan yazınla ilişkilendirerek anlatmayı içeren son aşamadır.'),
  ('Tematik analizde "temaların gözden geçirilmesi" aşamasında araştırmacı ne yapar?', 'Temaların kodlarla ve tüm veri setiyle uyumlu olup olmadığını denetler, gerekirse birleştirir ya da ayırır', ['Katılımcılara demografik sorular içeren ek bir anket uygulayıp yanıtları temalarla eşleştirir', 'Temaları kaldırıp yalnızca sayısal sonuçları raporlar', 'Veri toplamaya hiç başlamadan temaları kesinleştirir'], 'Bu aşamada adaylar iki düzeyde sınanır: tema kendi kodlu alıntılarıyla tutarlı mı, ve temalar bütün veri setini doğru yansıtıyor mu?'),
  ('Tematik analizde "kod" ile "tema" arasındaki ilişki için hangisi doğrudur?', 'Tema, birçok kodu bir araya getiren ve araştırma sorusu açısından anlamlı bir örüntüyü anlatan daha geniş bir yapıdır', ['Kod ve tema aynı şeydir; yalnızca yazım biçimleri farklıdır', 'Tema tek bir cümleye verilen etikettir, kod ise bütün raporun başlığıdır', 'Kodlar yalnızca sayısal, temalar yalnızca görsel verilerden çıkar'], 'Kodlar verinin küçük parçalarına verilen etiketlerdir; temalar bu kodların ortak anlam etrafında örgütlenmesiyle oluşan daha soyut örüntülerdir.'),
  ('Braun ve Clarke\'a göre katılımcıların açıkça söylediklerine dayanan temalar ile bu söylemlerin altında yatan varsayım ve düşüncelere dayanan temalar sırasıyla nasıl adlandırılır?', 'Anlamsal (semantik) ve örtük (gizil) temalar', ['Örtük ve anlamsal temalar', 'Nicel ve nitel temalar', 'Tümevarımsal ve tümdengelimsel temalar'], 'Anlamsal temalar verinin açık anlamında kalır; örtük (latent) temalar ise söylenenin ardındaki fikirleri ve ideolojileri yorumlar.'),
  ('Tematik analizde temalar ve alt temalar arasındaki ilişkileri görselleştirmek için hazırlanan çizimlere ne ad verilir?', 'Tematik harita', ['Akış şeması ve PRISMA diyagramı', 'Saçılım grafiği', 'Histogram'], 'Tematik harita temaları, alt temaları ve aralarındaki bağlantıları gösterir; temaların gözden geçirilmesi aşamasında sık kullanılır.'),
  ('Bir araştırmacı öğrencilerin uzaktan eğitim deneyimlerine ilişkin görüşmelerde "ekran yorgunluğu", "göz ağrısı" ve "uzun süre oturma" kodlarını belirlemiştir. Bu kodları kapsayan en uygun tema hangisidir?', 'Uzaktan eğitimin bedensel yükü', ['Öğretmenle iletişimde aksaklıklar ve geç yanıtlar', 'Ailelerin ekonomik durumu ve gelir düzeyi', 'Sınav güvenliği ve kopya kaygısı'], 'Üç kod da uzaktan eğitimin bedene etkileriyle ilgilidir; bu ortak anlam onları tek bir tema altında toplar.'),
  ('Katılımcının kendi kullandığı bir ifadenin, tırnak içinde aynen kod adı olarak kullanılmasına ne ad verilir?', 'In vivo kodlama', ['Betimleyici kodlama ve konu etiketleme', 'Yapısal kodlama', 'Değer kodlaması'], 'In vivo kodlama katılımcının sesini korur; örneğin bir öğrencinin "okulda görünmez gibiyim" sözü doğrudan "görünmez gibiyim" kodu olur.'),
  ('Bir araştırmacı görüşme dökümlerinde "hayal kırıklığı", "gurur", "kaygı" gibi katılımcıların yaşadığı ya da dile getirdiği duyguları kodluyor. Bu kodlama türü hangisidir?', 'Duygu kodlaması', ['Yapısal kodlama', 'Süreç kodlaması', 'Değer kodlaması'], 'Duygu (emotion) kodlaması katılımcıların hatırladığı, yaşadığı ya da araştırmacının çıkarsadığı duyguları etiketler.'),
  ('CAQDAS kısaltması neyi ifade eder?', 'Bilgisayar destekli nitel veri analizi yazılımlarını', ['Nicel verilerin bilgisayarla kodlanmasını sağlayan istatistik paketlerini', 'Nitel araştırmalar için uluslararası etik kurul onay sistemini', 'Bilgisayarla yürütülen yapılandırılmış anket görüşmelerini'], 'CAQDAS (Computer Assisted Qualitative Data Analysis Software) NVivo, MAXQDA ve ATLAS.ti gibi programların genel adıdır.'),
  ('Merriam\'ın görüşme soru türlerinden "Bu okul için ideal bir öğretmen nasıl olurdu?" sorusu hangi türe örnektir?', 'İdeal durum sorusu', ['Şeytanın avukatı sorusu', 'Yorumlayıcı soru', 'Demografik soru'], 'İdeal durum soruları katılımcıdan olması gerekeni betimlemesini ister; böylece hem görüşleri hem de mevcut durumu nasıl değerlendirdiği ortaya çıkar.'),
  ('Görüşmeci "Anlattıklarınızdan, yeni müdürle birlikte toplantıların daha kısa sürdüğünü anlıyorum; böyle mi?" diye soruyor. Merriam\'a göre bu hangi soru türüdür?', 'Yorumlayıcı soru', ['Varsayımsal soru', 'Duygu sorusu', 'Duyusal (gözlem) sorusu'], 'Yorumlayıcı sorular görüşmecinin o ana kadar anladığı bir yorumu katılımcıya sunar; katılımcı onaylayabilir, düzeltebilir ya da genişletebilir.'),
  ('"Okulunuzda kaç öğretmen var ve rehberlik servisi haftada kaç gün açık?" gibi sorular Patton\'un sınıflamasında hangi türe girer?', 'Bilgi soruları', ['Duygu soruları', 'Görüş ve değer soruları', 'Duyusal sorular'], 'Patton\'a göre bilgi soruları katılımcının olgusal bilgisini ister; görüş ve değer soruları ise katılımcının düşüncelerini ve yargılarını ortaya çıkarır.'),
  ('"Sizce okulda telefon yasağı doğru bir karar mı?" sorusu Patton\'un görüşme soruları sınıflamasında hangi türdendir?', 'Görüş ve değer sorusu', ['Duyusal soru', 'Bilgi sorusu', 'Deneyim ve davranış sorusu'], 'Soru katılımcının bir konuya ilişkin yargısını ve değerlendirmesini ister; bu nedenle görüş ve değer sorusudur.'),
  ('Görüşme formunda soruların genel ve kolay sorulardan başlayıp giderek daha özel ve hassas konulara ilerleyecek biçimde dizilmesine ne ad verilir?', 'Huni tekniği', ['Kartopu tekniği', 'Ters huni ve kapanış tekniği', 'Delphi tekniği'], 'Huni tekniği katılımcının ısınmasını ve güven kazanmasını sağlar; hassas konulara görüşmenin ilerleyen bölümünde geçilir.'),
  ('Bir araştırmacı hazırladığı görüşme formunu asıl katılımcılarla kullanmadan önce benzer özellikte iki kişiyle deneme görüşmesi yapıyor. Bu uygulamanın temel amacı nedir?', 'Soruların anlaşılırlığını, sırasını ve süresini sınayıp formu düzeltmek', ['Bu iki görüşmenin verilerini asıl bulguların istatistiksel ortalamasına eklemek', 'Asıl katılımcıların görüşmeye katılmasını gereksiz kılmak', 'Etik kurul onayı yerine geçecek bir belge üretmek'], 'Pilot görüşme anlaşılmayan, yönlendirici ya da gereksiz soruları ve süre sorunlarını ortaya çıkarır; form buna göre düzenlenir.'),
  ('Nitel görüşme formu geliştirilirken soruların alan uzmanlarına incelettirilmesi en çok hangi katkıyı sağlar?', 'Soruların araştırma sorularını kapsayıp kapsamadığının ve açıklığının değerlendirilmesi', ['Katılımcıların görüşmeye zamanında gelmesinin ve sonuna kadar kalmasının garanti altına alınması', 'Görüşmelerin ses kaydına gerek kalmadan yapılabilmesi', 'Soruların katılımcılara önceden ezberletilmesi'], 'Uzman görüşü, soruların araştırma amacına uygunluğunu, anlaşılırlığını ve yönlendirici olup olmadığını denetlemeye yardım eder.'),
  ('Nitel bir görüşme formunda ana soruların yanında "Bu konuda bir örnek verebilir misiniz?" gibi önceden yazılmış yardımcı soruların yer almasının amacı nedir?', 'Ana soru yeterli ayrıntı getirmediğinde derinleştirmeye hazır olmak', ['Görüşmeyi tamamen yapılandırılmış bir ankete dönüştürmek ve esnekliği kaldırmak', 'Katılımcının yanıtını önceden belirlemek', 'Görüşme süresini en aza indirmek'], 'Yardımcı (sonda) sorular görüşmecinin ana soruyu derinleştirmesine yardımcı olur; ancak her görüşmede hepsi kullanılmak zorunda değildir.'),
  ('Nitel görüşmelerde "Kullandığınız yöntemlerden memnun musunuz?" gibi evet-hayır yanıtlı sorular yerine hangi tür sorular tercih edilir?', 'Katılımcıyı anlatmaya davet eden açık uçlu sorular', ['Yalnızca tek sözcükle yanıtlanabilen kapalı uçlu sorular', 'Beşli derecelendirme ölçeği soruları', 'Doğru-yanlış biçimindeki bilgi soruları'], 'Nitel görüşmenin amacı derinlemesine anlatım elde etmektir; "Kullandığınız yöntemleri nasıl değerlendiriyorsunuz?" gibi açık uçlu biçimler bunu sağlar.'),
  ('Odak grup görüşmelerinde katılımcı sayısı için alan yazında en sık önerilen aralık hangisidir?', 'Yaklaşık 6–10 kişi', ['Yaklaşık 2–3 kişi', 'Yaklaşık 20–25 kişi', 'Yaklaşık 40–50 kişi'], '6–10 kişilik gruplar hem çeşitli görüşlerin çıkmasına hem de herkesin konuşabilmesine olanak verir; çok küçük gruplar etkileşimi, çok büyükler katılımı sınırlar.'),
  ('Odak grup oluştururken katılımcıların birbirini önceden tanımayan kişilerden seçilmesi sıklıkla önerilir. Bunun temel gerekçesi nedir?', 'Var olan ilişkilerin ve hiyerarşilerin konuşmaları kısıtlamasını önlemek', ['Katılımcıların görüşme sonunda birbirleriyle hiç konuşmamasını güvence altına almak', 'Grubun daha hızlı ve kısa sürede dağılmasını sağlamak', 'Moderatörün katılımcıların adlarını öğrenmesini gereksiz kılmak'], 'Birbirini tanıyan kişiler (ör. aynı iş yerindekiler) önceki ilişkiler nedeniyle bazı konuları açmaktan kaçınabilir; ancak bazı çalışmalarda doğal gruplar bilerek tercih edilir.'),
  ('Bir odak grup tartışmasının başında moderatörün katılımcılara kısa bir reklam filmi izletmesi ya da birkaç ürün ambalajı göstermesinin amacı nedir?', 'Tartışmayı başlatacak ortak bir uyarıcı sağlamak', ['Katılımcıların dikkatini dağıtıp oturumu uzatmak', 'Katılımcıların gösterilen ürünleri oturum sonunda satın almasını sağlamak', 'Görüşme sorularına gerek kalmamasını sağlamak'], 'Uyarıcı materyaller (video, görsel, örnek ürün) katılımcıların aynı şey üzerine konuşmasını sağlar ve tartışmayı somutlaştırır.'),
  ('Bir odak grup çalışmasında kaç oturum yapılacağına karar verilirken en sık kullanılan ölçüt hangisidir?', 'Yeni oturumların artık yeni görüş getirmemesi', ['Her ilde mutlaka tek bir oturum yapılması kuralı', 'Oturum sayısının her durumda 100 olması zorunluluğu', 'Moderatörün kaç gün boş olduğu'], 'Genellikle her katılımcı kesimi için birkaç oturum planlanır ve yeni oturumlar benzer görüşleri tekrarlamaya başladığında durulur.'),
  ('Katılımcıların belirli bir süre boyunca (ör. iki hafta) her gün yaşadıklarını, duygularını ya da etkinliklerini kendilerinin kaydettiği nitel veri toplama yöntemine ne ad verilir?', 'Günlük (diary) yöntemi', ['Odak grup görüşmesi', 'Delphi tekniği', 'Yapılandırılmış gözlem'], 'Günlük yöntemi olayları yaşandığı zamana yakın kaydettiği için hatırlama yanlılığını azaltır ve gündelik değişimleri izlemeyi sağlar.'),
  ('Eğitim araştırmalarında sık kullanılan, katılımcılardan "Öğretmen ... gibidir, çünkü ..." cümlesini tamamlamalarının istendiği nitel veri toplama tekniğinin adı nedir?', 'Metafor analizi', ['Kritik olay tekniği', 'Repertuvar ızgara tekniği', 'Nominal grup tekniği'], 'Metafor çalışmalarında katılımcıların ürettiği benzetmeler ve "çünkü" ile verilen gerekçeler kavramsal kategoriler altında toplanır; böylece bir kavramın zihinsel imgeleri ortaya çıkar.'),
  ('Saha çalışması sırasında beklenmedik biçimde ortaya çıkan bir fırsatı (ör. bir köyde yapılacak bir düğünü) değerlendirerek örnekleme yeni durum eklemeye ne ad verilir?', 'Fırsatçı (ortaya çıkan) örnekleme', ['Sistematik örnekleme', 'Tabakalı rastgele örnekleme', 'Ölçüt örneklemesi'], 'Fırsatçı örnekleme nitel desenin esnekliğinin bir sonucudur; araştırmacı sahada gelişen olaylara göre örneklemi genişletebilir.'),
  ('Bir araştırmacı kırsal, kentsel ve büyükşehir okullarından ayrı ayrı az sayıda öğretmen seçerek her alt grubun deneyimini karşılaştırmak istiyor. Bu amaçlı örnekleme türü hangisidir?', 'Tabakalı amaçlı örnekleme', ['Tabakalı rastgele örnekleme', 'Homojen örnekleme', 'Kartopu örneklemesi'], 'Tabakalı amaçlı örneklemede alt gruplar belirlenir ve her birinden amaçlı olarak durum seçilir; amaç istatistiksel temsil değil, alt gruplar arası karşılaştırmadır.'),
  ('Nitel araştırmalarda "bilgi zengini durum" (information-rich case) kavramı neyi ifade eder?', 'Araştırma sorusuyla ilgili derinlemesine bilgi sunabilecek durum ya da kişiyi', ['Geliri en yüksek, eğitim düzeyi en ileri ve toplumsal statüsü en güçlü olan katılımcıyı', 'Görüşmede en uzun konuşan kişiyi', 'Çok sayıda belge biriktirmiş kurumları'], 'Patton\'a göre amaçlı örneklemenin mantığı, araştırmanın amacı açısından çok şey öğrenilebilecek durumları seçmektir; zenginlik ekonomik değil bilgiyle ilgilidir.'),
  ('Bir görüşme dökümünde "ıı", "şey" gibi dolgu sözcüklerinin, tekrarların ve duraksamaların temizlenip metnin okunabilir yazı diline yaklaştırıldığı döküm yaklaşımına ne ad verilir?', 'Temizlenmiş (denatüralize) döküm', ['Kelimesi kelimesine Jefferson dökümü', 'Doğalcı (natüralize) döküm', 'Fonetik döküm ve ses çözümleme'], 'Oliver ve arkadaşlarının ayrımında temizlenmiş döküm içeriğe odaklanan çalışmalar için uygundur; konuşmanın nasıl gerçekleştiğini inceleyen çalışmalarda ise ayrıntılı döküm gerekir.'),
  ('Aşağıdaki çalışmalardan hangisinde temizlenmiş (yalnızca içerik odaklı) bir döküm yeterli olabilir?', 'Öğretmenlerin yeni müfredata ilişkin görüşlerinin tematik analizi', ['Doktor-hasta görüşmelerinde sıra alma düzeninin konuşma çözümlemesi', 'Bir siyasetçinin konuşmasındaki duraksamaların söylem analizi', 'Çocukların konuşmasında kekemelik örüntülerinin incelenmesi'], 'Tematik analizde ne söylendiği önemlidir; konuşmanın biçimsel ayrıntıları ise konuşma çözümlemesi ya da söylem analizi gibi yaklaşımlarda vazgeçilmezdir.'),
  ('Otomatik konuşma tanıma yazılımıyla oluşturulan görüşme dökümleri için en doğru uygulama hangisidir?', 'Dökümün ses kaydıyla karşılaştırılıp düzeltilmesi', ['Dökümün hiç kontrol edilmeden doğrudan kodlanması', 'Ses kaydının döküm bittikten hemen sonra katılımcıya sorulmadan internette paylaşılması', 'Yazılımın anlamadığı bölümlerin araştırmacı tarafından tahminle doldurulması'], 'Otomatik dökümler özellikle aksanlarda, yerel sözcüklerde ve üst üste konuşmalarda hata yapar; araştırmacının kaydı dinleyerek düzeltmesi gerekir.'),
  ('Nitel araştırmacıların görüşme dökümlerini kendilerinin yapmasının sık dile getirilen bir yararı nedir?', 'Döküm sırasında veriyi yakından tanıyıp ilk çözümleme fikirlerini edinmeleri', ['Dökümün başka birine yaptırılmasından her zaman daha kısa sürmesi', 'Dökümün bu durumda hiçbir yazım ya da anlam hatası içermemesinin tümüyle güvence altında olması', 'Ses kaydının saklanma gereğini ortadan kaldırması'], 'Dökümü yapmak zaman alıcıdır ama araştırmacıyı verinin içine sokar; birçok yazar bunu çözümlemenin ilk adımı olarak görür.'),
  ('Nitel araştırmaların raporlanması için Tong, Sainsbury ve Craig\'in 2007\'de geliştirdiği ve özellikle görüşme ve odak grup çalışmalarına yönelik 32 maddelik kontrol listesi hangisidir?', 'COREQ', ['CONSORT', 'PRISMA', 'STROBE'], 'COREQ (Consolidated Criteria for Reporting Qualitative Research) araştırma ekibi ve düşünümsellik, çalışma deseni ve analiz-bulgular başlıklarında 32 madde içerir.'),
  ('Nitel bir raporda katılımcı alıntılarının sonuna "(Ö7, kadın, 15 yaş)" gibi kodlar eklenmesinin amacı nedir?', 'Alıntıların farklı katılımcılardan geldiğini göstermek ve kimliği gizleyerek bağlam vermek', ['Katılımcıların gerçek kimliklerinin okurlar tarafından kolayca bulunabilmesini ve doğrulanabilmesini sağlamak', 'Alıntıların sayısal ortalamasını hesaplamayı kolaylaştırmak', 'Alıntıların araştırmacı tarafından yazıldığını belirtmek'], 'Katılımcı kodları, bulguların tek bir kişiye dayanmadığını gösterir ve okura bağlam sunar; aynı zamanda gerçek adların kullanılmasını önler.'),
  ('Howard Becker\'ın ortaya attığı ve Joseph Maxwell\'in nitel raporlama için önerdiği "yarı-istatistik" (quasi-statistics) uygulaması neyi ifade eder?', '"Çoğu", "birkaçı" gibi ifadelerin yerine basit sayımların kullanılarak iddiaların desteklenmesi', ['Nitel verilerden çoklu regresyon analizi yapılarak değişkenler arasında nedensel bir model kurulması', 'Bulguların istatistiksel anlamlılık testleriyle evrene genellenmesi', 'Alıntıların rastgele seçilerek rapora konması'], 'Becker\'ın kavramını benimseyen Maxwell\'e göre "20 katılımcının 17\'si" gibi basit sayılar, belirsiz nicelik ifadelerinin yarattığı abartı ya da küçümseme riskini azaltır; bu bir istatistiksel test değildir.'),
  ('Eylem araştırmasını geleneksel araştırmalardan ayıran temel amaç hangisidir?', 'Belirli bir ortamdaki uygulamayı iyileştirmek için sorunu araştırıp çözüme dönüştürmek', ['Evrensel yasalar bulup bunları tüm toplumlara genellemek ve var olan büyük kuramları sınamak', 'Değişkenler arasındaki ilişkiyi büyük örneklemlerle ölçmek', 'Geçmişteki olayları yalnızca arşiv belgeleriyle betimlemek'], 'Eylem araştırması uygulayıcıların kendi bağlamlarındaki sorunları sistemli biçimde inceleyip değişim yaratmasını hedefler; bilgi üretimi ile eylem iç içedir.'),
  ('Bir öğretmenin kendi sınıfında eylem araştırması yürütürken çalışmayı izleyen, sorular soran ve yorumlarına eleştirel geri bildirim veren bir meslektaşına ne ad verilir?', 'Eleştirel arkadaş', ['Kapı bekçisi', 'Kilit bilgi verici', 'Dış denetçi'], 'Eleştirel arkadaş (critical friend) güvenilir bir meslektaştır; destekleyici ama sorgulayıcı tutumuyla öğretmen-araştırmacının kör noktalarını görmesine yardım eder.'),
  ('Eylem araştırmasında veri toplamanın amacı aşağıdakilerden hangisinde en doğru belirtilmiştir?', 'Uygulanan eylemin etkilerini izleyip bir sonraki döngüyü planlamaya kanıt sağlamak', ['Bir hipotezi kesin olarak doğrulayıp araştırmayı tek bir döngüde bitirmek ve sonra yayımlamak', 'Yalnızca araştırmacının kişisel görüşünü belgelemek', 'Sınıftaki öğrencileri başarılarına göre sıralamak'], 'Eylem araştırmasında veri, yapılan değişikliğin nasıl işlediğini anlamak ve yansıtma aşamasında yeni kararlar almak için toplanır.'),
  ('Bir okulda öğretmenler, veliler ve öğrenciler birlikte okulun bahçesinin kullanımına ilişkin bir sorunu tanımlayıp veri topluyor, çözüm uyguluyor ve sonuçları birlikte değerlendiriyor. Bu çalışmanın en belirgin özelliği nedir?', 'Paydaşların araştırmanın ortağı olarak sürece katılması', ['Araştırmacının katılımcılardan tamamen bağımsız ve görünmez kalması', 'Yalnızca yöneticinin görüşlerinin veri olarak kullanılması', 'Verilerin yalnızca deney ve kontrol grubu karşılaştırmasıyla çözümlenmesi'], 'Katılımcı yaklaşımlarda araştırma "üzerinde" değil "birlikte" yapılır; sorunu yaşayanlar sorunun tanımına ve çözümüne doğrudan katılır.'),
  ('Nitel araştırmalarda toplanan verilerin büyük bölümü hangi biçimdedir?', 'Sözcükler, anlatılar ve görüntüler', ['Yalnızca ölçek puanları ve ortalamalar', 'Yalnızca laboratuvar ölçüm değerleri', 'Yalnızca yüzdeler ve oranlar'], 'Nitel veri; görüşme dökümleri, alan notları, belgeler, fotoğraflar ve videolar gibi sözel ve görsel malzemeden oluşur.'),
  ('Nitel bir çalışmanın bulgular bölümü genellikle nasıl sunulur?', 'Temalar halinde, betimleme ve katılımcı alıntılarıyla', ['Yalnızca hipotez testlerinin p değerleriyle', 'Yalnızca regresyon katsayılarını gösteren denklemlerle', 'Yalnızca frekans tabloları ve histogramlarla'], 'Nitel raporlar anlatı biçimindedir; temalar açıklanır, örneklerle ve alıntılarla desteklenir.'),
  ('Aşağıdakilerden hangisi nitel araştırmanın bir özelliği değildir?', 'Örneklemin evreni istatistiksel olarak temsil etmesinin zorunlu olması', ['Verilerin doğal ortamda toplanması', 'Araştırmacının veri toplama sürecinde etkin ve doğrudan bir rol üstlenmesi', 'Katılımcıların bakış açısının ve kendi sözcüklerinin ön plana çıkarılması'], 'Nitel araştırmada örneklem amaçlı seçilir ve istatistiksel temsil hedeflenmez; diğer seçenekler nitel araştırmanın temel özellikleridir.'),
  ('Nitel araştırmalarda genellikle önceden bir hipotez kurulup sınanmamasının nedeni nedir?', 'Amacın önceden kurulmuş bir önermeyi sınamak değil, olguyu keşfetmek ve anlamak olması', ['Nitel araştırmalarda hipotez kurmanın etik kurullar ve yönetmeliklerce açıkça yasaklanmış olması', 'Hipotezlerin yalnızca kimya deneylerinde kullanılabilmesi', 'Nitel araştırmacıların konuyla ilgili hiçbir şey okumamış olması'], 'Nitel araştırma çoğunlukla keşfedicidir; hipotezler ve kuramsal önermeler sınanmak yerine çalışmanın sonunda veriden üretilebilir.'),
  ('Nicel araştırmada "değişken" kavramının yerini nitel araştırmada çoğunlukla hangi kavramlar alır?', 'Anlam, deneyim ve süreç', ['Bağımsız ve bağımlı değişken', 'Standart sapma ve varyans', 'Kontrol grubu ve plasebo'], 'Nitel araştırma olguları ölçülebilir değişkenlere ayırmak yerine insanların deneyimlerine yüklediği anlamları ve bunların zaman içindeki süreçlerini inceler.'),
  ('Bir araştırmacının sahada gözlem sırasında tuttuğu, olayları, konuşmaları ve kendi izlenimlerini içeren yazılı kayıtlara ne ad verilir?', 'Alan notları', ['Ölçek puanları', 'Kod kitabı', 'Örneklem çerçevesi'], 'Alan notları gözlem verisinin temel kaydıdır; betimleyici bölümler ve araştırmacının yorumlarını içeren yansıtıcı bölümler bulunur.'),
  ('Etnografik bir çalışmada bir topluluğun kullandığı araç gereçler, giysiler, el sanatları ve süs eşyaları gibi fiziksel nesnelerin veri olarak incelenmesine ne ad verilir?', 'Maddi kültür (artefakt) incelemesi', ['Kartopu örneklemesi', 'Kapalı uçlu anket', 'Deneysel manipülasyon'], 'Nesneler bir topluluğun değerleri, gündelik pratikleri ve ilişkileri hakkında ipuçları taşır; etnograflar bunları da veri olarak kullanır.'),
  ('Aşağıdakilerden hangisi nitel veri kaynağı olarak kullanılan bir doküman örneği değildir?', 'Bir ölçeğin Cronbach alfa katsayısı', ['Bir öğretmenin tuttuğu kişisel günlük', 'Bir okulun disiplin kurulu tutanakları', 'Bir gencin sosyal medya paylaşımları'], 'Günlükler, tutanaklar ve paylaşımlar yorumlanacak metinlerdir; Cronbach alfa ise nicel bir güvenirlik istatistiğidir.'),
  ('Nitel araştırmada "katılımcı" teriminin "denek" yerine tercih edilmesinin temel gerekçesi nedir?', 'Kişilerin araştırmaya etkin katkı veren bilgi kaynakları olarak görülmesi', ['Katılımcıların araştırmacıdan daha az bilgili ve konuya yabancı kişiler olarak kabul edilmesi', 'Kişilerin üzerinde deney yapılacağının vurgulanması', 'Katılımcıların adlarının yazılmasının zorunlu olması'], '"Denek" sözcüğü üzerinde işlem yapılan pasif bir nesneyi çağrıştırır; nitel araştırma ise kişileri kendi deneyimlerinin uzmanı olarak görür.'),
  ('Nitel araştırmada veri toplama ile veri analizinin ilişkisi için hangisi en doğrudur?', 'İkisi çoğu zaman iç içe ve döngüsel biçimde yürür', ['Analiz ancak tüm veriler toplandıktan yıllar sonra başlayabilir', 'Veri toplama analizden sonra yapılır', 'İkisi birbirinden tamamen bağımsızdır ve farklı kişilerce yürütülmek zorundadır'], 'Nitel araştırmacı ilk verileri toplarken çözümlemeye başlar; ortaya çıkan fikirler sonraki veri toplamayı yönlendirir.'),
  ('Creswell\'in önerisine göre nitel bir çalışmanın "merkezî sorusu" nasıl olmalıdır?', 'İncelenen olguyu en genel biçimde keşfetmeye açık, geniş bir soru', ['İki değişken arasındaki ilişkiyi yönlü biçimde öngören bir hipotez', 'Evet-hayır biçiminde yanıtlanan kapalı bir soru', 'Örneklem büyüklüğünü belirten sayısal bir soru'], 'Creswell nitel çalışmaların bir ya da iki geniş merkezî soruyla başlamasını ve bunların alt sorularla daraltılmasını önerir; soru keşfe açık olmalıdır.'),
  ('Nitel bir araştırma raporunun yöntem bölümünde, nicel raporlardan farklı olarak genellikle yer alan başlık hangisidir?', 'Araştırmacının rolü', ['Güç analizi ve örneklem hesabı', 'Hipotezlerin istatistiksel sınanması', 'Normallik varsayımının denetimi'], 'Nitel araştırmada araştırmacı veri toplama aracı olduğu için raporlarda araştırmacının konumu, deneyimi ve katılımcılarla ilişkisi ayrıca açıklanır.'),
  ('Nitel araştırmalarda alan yazının rolüne ilişkin hangisi doğrudur?', 'Alan yazın sorunu çerçevelemeye yardım eder ama çoğu zaman bulgularla tartışmada daha yoğun kullanılır', ['Nitel araştırmalarda alan yazına hiç başvurulmaz ve kaynakça yazılmaz', 'Alan yazın yalnızca sınanacak hipotezleri belirleyen tek kaynaktır ve bulgular onunla tartışılmaz', 'Alan yazın yalnızca raporun en sonuna, okunmadan eklenir'], 'Nitel çalışmalarda alan yazın araştırmanın gerekçesini ortaya koyar; ancak kategorilerin önceden belirlenmesini önlemek için bulguların yorumunda ve karşılaştırılmasında daha etkin kullanılır.'),
  ('Bir lise öğrencisi görüşmede "Sınav haftası gelince midem bulanıyor, gece uyuyamıyorum" diyor. Bu ifadeye verilebilecek en uygun betimleyici kod hangisidir?', 'Sınav kaygısının bedensel belirtileri', ['Okul yönetimiyle iletişim', 'Ders dışı sosyal ve sportif etkinliklere katılım', 'Arkadaşlarla zaman geçirme ve oyun'], 'İfade sınav dönemine bağlı mide bulantısı ve uykusuzluk gibi bedensel tepkileri anlatır; kod bu içeriği özetlemelidir.'),
  ('Bir çalışmada "maddi destek", "duygusal destek" ve "bilgi desteği" kodları oluşturulmuştur. Bu kodları kapsayabilecek en uygun üst kategori hangisidir?', 'Sosyal destek türleri', ['Akademik başarı göstergeleri', 'Fiziksel çevre koşulları', 'Teknoloji kullanım alışkanlıkları'], 'Üç kod da kişinin çevresinden aldığı farklı destek biçimlerini anlatır; bu ortak anlam "sosyal destek türleri" kategorisinde toplanır.'),
  ('Bir veli "Öğretmenle konuşmaya gittiğimde hep ayakta, kapıda konuşuyoruz; içeri buyur edilmiyoruz" diyor. Bu ifadeye en uygun kod hangisidir?', 'Okulda velinin dışlanmışlık hissi', ['Velinin çocuğuna ödevde yardım etmesi', 'Okul binasının mimari yetersizliği', 'Öğretmenin ders anlatım yöntemi'], 'Velinin anlattığı durum okulun kendisini kabul etmediği algısını yansıtır; kod bu deneyimin anlamını yakalamalıdır.'),
  ('Bir araştırmacı "öğretmenden çekinme", "soru sormaktan kaçınma" ve "yanlış yapma korkusu" kodlarını bir arada inceliyor. Bu kodları birleştirebilecek en uygun tema hangisidir?', 'Sınıfta sessiz kalma nedenleri', ['Okul servisinin işleyişi', 'Kantin fiyatları ve beslenme', 'Ders kitaplarının fiziksel kalitesi'], 'Üç kod da öğrencilerin sınıfta konuşmamasının ardındaki çekinceleri anlatır; ortak tema bu davranışın nedenleridir.'),
  ('Kodlamada bir veri parçasına, parçanın tamamında geçmeyen bir anlamı yüklemekten kaçınmak için araştırmacı ne yapmalıdır?', 'Kodun alıntının söylediğiyle desteklenip desteklenmediğini bağlamıyla birlikte kontrol etmek', ['Kodları önceden belirleyip veriyi okumadan atamak', 'Katılımcının söylemediği ama araştırmacının beklediği anlamları da eklemek', 'Her alıntıya rastgele bir kod vermek'], 'Kodlar veriye dayanmalıdır; araştırmacı yorum yaparken kodu alıntının ve bağlamının gerçekten desteklediğinden emin olmalıdır.'),
  ('Bir araştırmacı öğretmen görüşmelerinde "zaman yetmiyor", "müfredat çok yoğun" ve "etkinliklere süre kalmıyor" ifadelerini aynı kod altında topluyor. En uygun kod adı hangisidir?', 'Zaman baskısı', ['Velilerle çatışma', 'Meslektaş dayanışması', 'Mesleki ödüller'], 'Üç ifadenin ortak noktası öğretim süresinin yetersiz algılanmasıdır; "zaman baskısı" bu ortak anlamı özetler.'),
  ('Bir katılımcı "Mahalleye taşındığımızda kimseyi tanımıyorduk, sonra cami derneğinde gönüllü oldum, şimdi herkes beni tanıyor" diyor. Bu parçaya hangi süreç kodu en uygundur?', 'Gönüllülük yoluyla topluluğa katılma', ['Ekonomik zorluklarla ve işsizlikle başa çıkma', 'Sağlık hizmetlerine erişim', 'Eğitim düzeyini yükseltme'], 'Parça yeni gelen birinin gönüllü faaliyet aracılığıyla toplulukta yer edinme sürecini anlatır; süreç kodu bu eylem dizisini adlandırır.'),
  ('Nitel çözümlemede bir kategorinin "özellikleri"ni belirlemeye yönelik aşağıdaki sorulardan hangisi uygundur?', 'Bu destek ne zaman, kimden ve hangi biçimde geliyor?', ['Bu destek kaç kişiye anket uygulanarak ölçüldü?', 'Bu destek hangi istatistik testine uygundur?', 'Bu desteği anlatan katılımcının telefon numarası nedir?'], 'Kategorinin özellikleri onun zaman, kaynak ve biçim gibi boyutlarıdır; bu sorular kategoriyi kavramsal olarak zenginleştirir.'),
  ('Görüşmeci katılımcının son söylediği birkaç sözcüğü soru tonuyla tekrar ederek ("Kendinizi yalnız hissettiniz...?") onu anlatmaya devam etmeye teşvik ediyor. Bu tekniğe ne ad verilir?', 'Yansıtma (yankı) tekniği', ['Yönlendirici (ima eden) soru', 'Huni tekniği', 'Kapanış sorusu'], 'Yansıtma, katılımcının kendi sözlerini geri vererek ilgiyi gösterir ve görüşmecinin yeni bir içerik eklemeden derinleşmeyi sağlar.'),
  ('Görüşmeci bir bölümden diğerine geçerken "Şimdiye kadar okul yıllarınızı konuştuk; şimdi biraz da iş yaşamınıza geçmek istiyorum" diyor. Bu ifadenin işlevi nedir?', 'Katılımcıyı konu değişikliğine hazırlayan bir geçiş cümlesi olması', ['Katılımcıyı önceden belirlenmiş belirli bir yanıta yönlendiren bir soru olması', 'Görüşmeyi sonlandıran bir kapanış ifadesi olması', 'Katılımcıdan onam alan bir ifade olması'], 'Geçiş cümleleri görüşmenin akışını düzenler ve katılımcının yeni konuya zihinsel olarak hazırlanmasını sağlar.'),
  ('Bir görüşmeci görüşme boyunca "hı-hı", "anlıyorum" gibi kısa sesler çıkarıyor, başını sallıyor ve katılımcının sözünü kesmiyor. Bu davranışlar topluca neyi oluşturur?', 'Etkin dinleme', ['Yönlendirme', 'Standartlaştırma', 'Yataylaştırma'], 'Etkin dinleme, sözel ve sözel olmayan işaretlerle katılımcıya dinlendiğini hissettirir ve anlatımı sürdürmesini kolaylaştırır.'),
  ('Derinlemesine görüşmelerde süre konusunda genel öneri hangisidir?', 'Süre konuya ve katılımcıya göre değişir; çoğu görüşme yaklaşık 45–90 dakika sürer', ['Her görüşme tam olarak 5 dakikada bitirilmelidir', 'Görüşmeler hiçbir zaman 3 saatten kısa olmamalıdır', 'Görüşme süresi katılımcının yaşının iki katı dakika olmalıdır'], 'Derinlemesine görüşmeler katılımcıyı yormadan zengin anlatım alacak kadar uzun tutulur; yorgunluk belirtileri görülürse ara verilebilir ya da ikinci görüşme yapılabilir.'),
  ('Bir görüşmeci aynı katılımcıyla farklı zamanlarda birden çok görüşme yapmayı planlıyor. Bunun tek görüşmeye göre bir avantajı nedir?', 'Güvenin derinleşmesi ve ilk görüşmede çıkan konuların sonradan ayrıntılandırılabilmesi', ['Her görüşmenin bir öncekinin tam olarak aynısı olacağının ve tutarlılığın güvence altında olması', 'Katılımcı sayısının istatistiksel olarak artmış sayılması', 'Döküm yapma gereğinin ortadan kalkması'], 'Tekrarlanan görüşmeler ilişkiyi güçlendirir, araştırmacıya ilk görüşmeyi çözümleyip yeni sorular hazırlama fırsatı verir.'),
  ('"Nitel araştırma kolaydır; birkaç kişiyle konuşup izlenim yazmak yeterlidir" görüşüne verilebilecek en uygun yanıt hangisidir?', 'Nitel araştırma sistemli veri toplama, ayrıntılı çözümleme ve şeffaf raporlama gerektirir', ['Bu görüş doğrudur; nitel araştırmada izlenmesi gereken hiçbir yöntem kuralı ya da ölçüt yoktur', 'Nitel araştırma yalnızca istatistik bilenlerce yapılabilir', 'Nitel araştırma yalnızca laboratuvarda yapılabilir'], 'Nitel araştırma örneklem seçimi, veri toplama protokolleri, kodlama, güvenirlik stratejileri ve düşünümsellik gibi titiz süreçler içerir; izlenim yazmakla eşdeğer değildir.'),
  ('Nitel araştırmaların başlıca sınırlılıklarından biri aşağıdakilerden hangisidir?', 'Veri toplama ve çözümlemenin çok zaman alması', ['Katılımcıların bakış açısını hiç yansıtamaması', 'Bağlamı tamamen göz ardı etmesi', 'Yalnızca çok büyük örneklemlerle yapılabilmesi'], 'Görüşmeler, dökümler, kodlama ve yorum uzun süre gerektirir; bu nedenle nitel çalışmalar genellikle az sayıda katılımcıyla yürütülür.'),
  ('"Nitel ve nicel araştırma birbirine düşmandır; biri doğruysa diğeri yanlıştır" görüşüne en uygun yanıt hangisidir?', 'İki yaklaşım farklı soruları yanıtlar ve uygun durumlarda birbirini tamamlayabilir', ['Yalnızca nicel araştırma bilimseldir, nitel araştırma terk edilmelidir', 'Yalnızca nitel araştırma bilimseldir, nicel araştırma terk edilmelidir', 'İki yaklaşım tamamen aynıdır; aralarında yöntem, amaç ya da veri bakımından hiçbir fark yoktur'], 'Araştırma sorusu yöntemi belirler; karma yöntem araştırmaları iki yaklaşımın güçlü yanlarını birleştirebileceğini gösterir.'),
  ('Nitel araştırmada "anekdotçuluk" eleştirisi neyi ifade eder?', 'Sonuçların sistemli çözümleme yerine birkaç çarpıcı örneğe dayandırılması', ['Araştırmanın yalnızca fıkralar üzerine yapılması', 'Katılımcıların gerçek ad ve kimliklerinin raporda açıkça yazılması', 'Örneklemin rastgele seçilmesi'], 'Anekdotçuluk, verinin bütününü temsil edip etmediği belirsiz örneklerin kanıt gibi kullanılmasıdır; olumsuz durum analizi ve şeffaf raporlama bu riski azaltır.'),
  ('Verilerin şiir, tiyatro, resim ya da dans gibi sanatsal biçimlerle toplanabildiği, çözümlenebildiği ya da sunulabildiği nitel yaklaşımlara genel olarak ne ad verilir?', 'Sanat temelli araştırma', ['Deneysel araştırma', 'Tarama araştırması', 'Korelasyonel ve nedensel karşılaştırmalı araştırma'], 'Sanat temelli araştırmalar duygusal ve bedensel deneyimleri sözcüklerin ötesinde ifade etmeyi ve farklı kitlelere ulaşmayı amaçlar.'),
  ('Bir araştırmacı bir belediyenin yürüttüğü "mahalle bostanları" projesini, başlangıcından bitişine kadar; belgeler, görüşmeler ve gözlemlerle inceleyerek projenin nasıl işlediğini anlatmak istiyor. Hangi desen en uygundur?', 'Durum çalışması', ['Olgubilim', 'Konuşma çözümlemesi', 'Fenomenografi'], 'Zaman ve mekânla sınırlı tek bir programın çoklu veri kaynaklarıyla derinlemesine incelenmesi durum çalışmasının tipik örneğidir.'),
  ('Bir araştırmacı farklı illerdeki dört üniversitenin uzaktan eğitime geçiş sürecini ayrı ayrı inceleyip karşılaştırmak istiyor. Bu çalışmada "durum" nedir?', 'Her bir üniversitenin uzaktan eğitime geçiş süreci', ['Araştırmacının kendisi', 'Çalışmanın yayımlanacağı dergi', 'Üniversitelerin bulunduğu illerin toplam nüfusu ve yüzölçümü'], 'Durum çalışmasında incelenen sınırlı sistem durumdur; burada her üniversitenin geçiş süreci ayrı bir durum olarak ele alınmaktadır.'),
  ('Başka araştırmacılar tarafından toplanmış ve arşivlenmiş nitel verilerin (ör. görüşme dökümlerinin) yeni bir araştırma sorusu için yeniden çözümlenmesine ne ad verilir?', 'Nitel ikincil analiz', ['Meta-analiz', 'Pilot uygulama ve ön deneme', 'Kartopu örneklemesi'], 'Nitel ikincil analiz arşivlenmiş verileri yeniden kullanır; ancak araştırmacı verinin toplandığı bağlamda bulunmadığı için bağlamı belgelerden yeniden kurmak zorundadır.'),
  ('Bir kişinin kendi yaşamını kendisinin yazarak anlattığı metne ne ad verilir?', 'Otobiyografi', ['Biyografi', 'Monografi', 'Etnografi'], 'Otobiyografide anlatıcı ile yaşamı anlatılan kişi aynıdır; biyografide ise yaşamı başka biri yazar.'),
  ('Türkçe kaynaklarda durum çalışması için kullanılan diğer adlardan biri hangisidir?', 'Örnek olay incelemesi', ['Tarama modeli', 'Deneme modeli', 'Korelasyonel model'], '"Durum çalışması", "vaka çalışması" ve "örnek olay incelemesi" terimleri İngilizcedeki "case study" karşılığında kullanılır.'),
  ('Nitel bir çalışmada fotoğraf, video, çizim ve harita gibi veriler genel olarak hangi başlık altında toplanır?', 'Görsel veriler', ['Sayısal veriler', 'Ölçek verileri', 'Deneysel veriler'], 'Görsel veriler, sözel verilerin yanında nitel araştırmanın önemli bir kaynağıdır ve kendi çözümleme yaklaşımlarına sahiptir.'),
  ('Bir görüşmeyi gündelik bir sohbetten ayıran temel özellik hangisidir?', 'Belirli bir araştırma amacına yönelik planlı ve sistemli olması', ['Hiçbir zaman soru sorulmaması', 'Yalnızca iki dakika sürmesi', 'Katılımcının her soruya yalnızca evet ya da hayır diyerek yanıt verebilmesi'], 'Görüşme sohbete benzeyebilir ama araştırma sorusuna hizmet eden bir amacı, planı ve kayıt düzeni vardır.'),
  ('Patton\'ın görüşme soruları sınıflamasında "Kaç yıldır bu okulda görev yapıyorsunuz?" gibi bir soru hangi türe girer?', 'Geçmiş ve demografik bilgi sorusu', ['Duygu ve hissetme sorusu', 'Görüş ve değer sorusu', 'Varsayımsal soru'], 'Yaş, kıdem, eğitim gibi katılımcıyı tanımlayan bilgileri isteyen sorular demografik ve geçmiş bilgi sorularıdır.'),
  ('Odak grup görüşmesinde tartışmayı yöneten, soruları soran ve herkesin konuşmasını sağlamaya çalışan kişiye ne ad verilir?', 'Moderatör', ['Raportör', 'Kapı bekçisi', 'Kilit bilgi verici'], 'Moderatör tartışmanın akışını yönetir; raportör ise tartışmaya katılmadan not tutar.'),
  ('Nitel bir raporun "katılımcılar" bölümünde genellikle aşağıdakilerden hangisi yer alır?', 'Katılımcıların kimliklerini açığa çıkarmayan temel özellikleri', ['Katılımcıların ev adresleri, telefon numaraları ve çalıştıkları kurumların tam adları', 'Katılımcıların kimlik numaraları ve fotoğrafları', 'Katılımcıların istatistiksel güç hesabı tabloları'], 'Okurun bağlamı anlaması için katılımcıların ilgili özellikleri özetlenir; kimliği belirleyecek bilgiler verilmez.'),
  ('Nitel araştırmalarda "bağlam" kavramına önem verilmesinin nedeni nedir?', 'Davranışların ve sözlerin anlamının içinde bulunduğu koşullara göre değişebilmesi', ['Bağlamın göz önüne alınmasının istatistiksel ölçme hatasını tamamen ortadan kaldırması', 'Bağlamın örneklem büyüklüğünü otomatik olarak artırması', 'Bağlamın yalnızca nicel çalışmalarda önemli olması'], 'Aynı söz ya da davranış farklı ortamlarda farklı anlamlar taşıyabilir; nitel araştırmacı bu nedenle olguyu bağlamından koparmadan inceler.'),
  ('Bir antropolog bir köyde yaptığı alan çalışmasında köyün yerleşim düzenini, evlerin, çeşmenin, okulun ve kahvenin yerini gösteren bir kroki çiziyor. Bu kroki alan çalışmasına nasıl katkı sağlar?', 'Mekânsal düzenin toplumsal ilişkilerle bağlantısını görmeye ve gözlemleri konumlandırmaya yardım eder', ['Köylülerle görüşme yapma ve onları gözlemleme gereğini tamamen ortadan kaldırır', 'Köyün nüfusunu kesin olarak hesaplamayı sağlar', 'Gözlemlerin istatistiksel anlamlılığını sınar'], 'Mekân toplumsal yaşamı biçimlendirir; krokiler kimin nerede toplandığını, hangi yolların kullanıldığını ve gözlemlerin nerede yapıldığını kaydeder.'),
  ('Krueger\'in odak grup soru sınıflamasında, herkesin kısa sürede yanıtlayabileceği ve katılımcıların kendilerini tanıtmasını sağlayan ilk soru türüne ne ad verilir?', 'Açılış sorusu', ['Anahtar soru', 'Kapanış sorusu', 'Geçiş sorusu'], 'Krueger\'e göre açılış soruları çözümlenmek için değil, herkesin bir kez konuşmasını ve grubun ısınmasını sağlamak için sorulur.'),
  ('Krueger\'in odak grup soru sınıflamasında, araştırmanın asıl amacına doğrudan yönelen ve tartışma süresinin en büyük bölümünün ayrıldığı sorular hangileridir?', 'Anahtar sorular', ['Açılış soruları', 'Giriş soruları', 'Kapanış soruları'], 'Anahtar sorular çözümlemenin odağındadır; genellikle iki ile beş anahtar soru bulunur ve her birine daha uzun zaman ayrılır.'),
  ('Sağlık deneyimleri üzerine yapılan bir görüşmede katılımcı görüşmeciden hangi ilacı kullanması gerektiği konusunda tavsiye istiyor. Görüşmeci hekim değildir. En uygun davranış hangisidir?', 'Uzman olmadığını belirtip katılımcıyı ilgili sağlık profesyoneline yönlendirmek', ['Kendi kişisel deneyimine dayanarak katılımcıya uygun gördüğü bir ilacı ve dozunu önermek', 'Soruyu hiç yanıtlamadan görüşmeyi kesmek', 'Katılımcıya internetten rastgele bir ilaç adı bulup söylemek'], 'Görüşmecinin rolü veri toplamaktır; uzmanlık dışı konularda tavsiye vermek katılımcıya zarar verebilir ve rol sınırlarını bulandırır.'),
  ('Görüşmeci görüşme biter bitmez, ortamı, katılımcının beden dilini, kayıt dışında söylenen genel izlenimleri ve kendi ilk düşüncelerini kısa bir metne yazıyor. Bu notların temel işlevi nedir?', 'Ses kaydında yer almayan bağlam bilgisini ve ilk çözümleme fikirlerini kaybetmemek', ['Görüşme dökümünün yerine geçip ses kaydını ve dökümü tümüyle gereksiz kılmak', 'Katılımcının kimliğini raporda açıklamak', 'Görüşmenin süresini istatistiksel olarak hesaplamak'], 'Görüşme sonrası notlar, kaydın yakalayamadığı atmosferi, sözel olmayan işaretleri ve araştırmacının sıcağı sıcağına yorumlarını korur.'),
  ('Bir görüşme ses kaydına alınırken görüşmecinin yine de kısa notlar tutması hangi amaca hizmet eder?', 'Sonradan sorulacak derinleştirme sorularını ve sözel olmayan önemli anları işaretlemek', ['Ses kaydının yasal olarak geçersiz olmasını önlemek', 'Katılımcının söylediklerini kelimesi kelimesine yazıp sonradan yapılacak dökümü gereksiz kılmak', 'Katılımcıya ne kadar hızlı yazdığını göstermek'], 'Kayıt sözleri saklar; notlar ise görüşmecinin o anda fark ettiği, dönülmesi gereken konuları ve jest, mimik gibi ipuçlarını kaydeder.'),
  ('Bir araştırmacı görüşmeye gitmeden önce ses kayıt cihazını ve yedeğini deniyor, pillerini ve depolama alanını kontrol ediyor. Bu hazırlığın amacı nedir?', 'Teknik bir aksaklık nedeniyle tekrarlanamayacak görüşme verisinin kaybolmasını önlemek', ['Katılımcının görüşme günü gelip sonradan görüşmeye katılmayı reddetmesini önceden engellemek', 'Görüşme sorularının sayısını azaltmak', 'Görüşmenin daha kısa sürmesini sağlamak'], 'Derinlemesine görüşme aynı biçimde yinelenemez; kayıt cihazının arızalanması veri kaybına yol açar. Yedek cihaz ve önceden deneme bu riski azaltır.'),
  ('Bir araştırmacı görüşme dosyalarını "Ö03_2024-04-12_gorusme1" gibi katılımcı kodu, tarih ve görüşme sırasını içeren bir düzenle adlandırıyor. Bu uygulamanın temel yararı nedir?', 'Verilerin düzenli, izlenebilir ve kimlik bilgisi içermeden yönetilmesi', ['Dosyaların internet arama motorlarında ve paylaşım sitelerinde kolayca bulunabilmesi', 'Katılımcıların gerçek adlarının herkesçe bilinmesi', 'Dosyaların boyutunun küçülmesi'], 'Tutarlı dosya adlandırma, veri yönetimini kolaylaştırır, denetim izine katkı sağlar ve gerçek adların dosya adlarında görünmesini önler.'),
  ('Bir araştırmacı sosyal medyada belirli bir etiketle (hashtag) paylaşılan iletileri toplayıp kullanıcıların bir olayı nasıl çerçevelediğini temalar halinde inceliyor. Bu çalışmada veri hangi türdendir?', 'Kendiliğinden üretilmiş çevrimiçi metin verisi', ['Araştırmacının kurduğu deney düzeneğinden elde edilen ölçüm verisi', 'Yapılandırılmış gözlem formuyla toplanan sıklık verisi', 'Laboratuvarda kaydedilen fizyolojik veri'], 'İletiler araştırma için değil, kullanıcıların kendi amaçlarıyla üretilmiştir; bu tür doğal oluşmuş metinler nitel içerik ya da söylem analiziyle incelenebilir.'),
  ('Türkçe nitel araştırma kaynaklarında "triangulation" kavramı için kullanılan ve farklı veri kaynaklarının, yöntemlerin ya da araştırmacıların bir arada kullanılmasını anlatan karşılık hangisidir?', 'Çeşitleme', ['Yataylaştırma', 'Kümeleme', 'Doygunluk'], 'Yıldırım ve Şimşek gibi Türkçe kaynaklarda triangulation "çeşitleme" ya da "üçgenleme" olarak karşılanır.'),
  ('Aşağıdakilerden hangisi nitel araştırmada kullanılan bir veri toplama aracıdır?', 'Yarı yapılandırılmış görüşme formu', ['Çoktan seçmeli standart başarı testi', 'Beşli Likert tipi tutum ölçeği', 'Kronometre ile tepki süresi ölçümü'], 'Yarı yapılandırılmış görüşme formu açık uçlu sorular aracılığıyla derinlemesine veri toplar; diğer araçlar sayısal veri üretir.'),
  ('Aşağıdakilerden hangisi bir nitel araştırma deseni değildir?', 'Ön test-son test kontrol gruplu deneysel desen', ['Olgubilim', 'Etnografi', 'Durum çalışması'], 'Ön test-son test kontrol gruplu desen nicel deneysel bir desendir; olgubilim, etnografi ve durum çalışması nitel desenlerdir.'),
  ('Katılımcıların bir forum sayfasında birkaç gün boyunca, istedikleri saatte soruları yanıtlayıp birbirlerinin yazdıklarına yorum yaptığı odak grup türüne ne ad verilir?', 'Eşzamansız çevrimiçi odak grup', ['Yüz yüze mini odak grup', 'Telefonla yapılandırılmış anket', 'Nominal grup tekniği'], 'Eşzamansız çevrimiçi odak grupta katılımcılar aynı anda bağlı olmak zorunda değildir; farklı saat dilimlerindeki ya da yoğun programlı kişiler için uygundur.'),
  ('Sınıfında eylem araştırması yürüten bir öğretmenin aşağıdakilerden hangisini veri kaynağı olarak kullanması en az uygundur?', 'Başka bir ildeki bir okulun yıllık bütçe tablosu', ['Öğretmenin tuttuğu yansıtıcı günlük', 'Öğrencilerin ürettiği ödev ve çalışmalar', 'Ders sonrası öğrencilerle yapılan kısa görüşmeler'], 'Eylem araştırması öğretmenin kendi sınıfındaki uygulamayı anlamaya yöneliktir; günlükler, öğrenci ürünleri ve görüşmeler bu amaca hizmet eder.'),
  ('Etnografik çalışmalarda bir topluluğun yaşamında olağan akışı bozan ve kültürel kuralları belirgin biçimde görünür kılan olaylara (ör. bir düğün, bir anlaşmazlık, bir cenaze) ne ad verilir?', 'Anahtar olaylar', ['Aykırı değerler', 'Kontrol değişkenleri', 'Kodlama birimleri'], 'Fetterman gibi yazarlar anahtar olayların çözümlenmesini etnografide önemli bir strateji sayar; bu olaylar grubun değerlerini yoğunlaşmış biçimde gösterir.'),
  ('"Gömülü kuram" (grounded theory) için Türkçe kaynaklarda kullanılan bir diğer karşılık hangisidir?', 'Temellendirilmiş kuram', ['Yapılandırılmış ve sınanmış kuram', 'Deneysel kuram', 'Varsayımsal kuram'], 'Grounded theory Türkçede "gömülü kuram", "temellendirilmiş kuram" ya da "veriye dayalı kuram" olarak karşılanır; hepsi kuramın veriden türetildiğini vurgular.'),
  ('"Olgubilim" teriminin Türkçe kaynaklarda sıkça kullanılan diğer karşılığı hangisidir?', 'Fenomenoloji', ['Etnometodoloji', 'Hermenötik', 'Fenomenografi'], 'Olgubilim, Yunanca "görünen" anlamındaki phainomenon sözcüğünden türeyen fenomenoloji teriminin Türkçe karşılığıdır.'),
  ('"Etnografi" sözcüğü Yunanca hangi iki sözcükten türemiştir?', 'Ethnos (halk, topluluk) ve graphein (yazmak)', ['Ethos (ahlak) ve logos (bilim)', 'Eidos (biçim, görünüş) ve graphein (yazmak)', 'Ethnos (halk) ve logos (bilim)'], 'Etnografi sözcük anlamıyla "halkın betimlenmesi, yazılması" demektir; bu ad yöntemin kültürü betimleme amacını yansıtır.'),
  ('Yorumlama bilimi anlamına gelen "hermenötik" teriminin adını, tanrıların mesajlarını insanlara ileten Yunan mitolojisindeki hangi figürle ilişkilendirildiği sıkça belirtilir?', 'Hermes', ['Apollon', 'Athena', 'Prometheus'], 'Hermenötik, Yunanca "yorumlamak" anlamındaki hermeneuein fiilinden gelir; bu sözcük geleneksel olarak haberci tanrı Hermes ile ilişkilendirilir.'),
  ('Nitel araştırma geleneklerinin tarihsel olarak en çok hangi iki disiplinin saha çalışmalarından beslendiği kabul edilir?', 'Antropoloji ve sosyoloji', ['Fizik ve kimya', 'Matematik ve astronomi', 'Muhasebe ve finans'], 'Antropolojideki etnografik alan çalışmaları ve Chicago Okulu sosyolojisi nitel araştırmanın temel kaynaklarıdır; sonradan eğitim, sağlık ve işletme gibi alanlara yayılmıştır.'),
  ('Nitel çözümlemede "betimleme" ile "yorumlama" arasındaki fark hangisinde doğru verilmiştir?', 'Betimleme söylenenleri düzenleyip aktarır; yorumlama bunların ne anlama geldiğini ve neden önemli olduğunu açıklar', ['Betimleme yalnızca sayısal tablolarla, yorumlama ise yalnızca fotoğraf ve çizimlerle yapılabilir', 'Yorumlama verilerden önce, betimleme raporun yayımlanmasından sonra yapılır', 'İkisi arasında hiçbir fark yoktur'], 'İyi bir nitel rapor yalnızca "ne söylendi"yi değil, bunun araştırma sorusu ve alan yazın açısından anlamını da tartışır.'),
  ('Bir metafor çalışmasında bir öğretmen adayı "Öğretmen bahçıvana benzer, çünkü her fidanın ihtiyacını bilip ona göre su ve güneş verir" yazmıştır. Bu metafor aşağıdaki kategorilerden hangisine en uygun düşer?', 'Bireysel farklılıkları gözeten, yetiştirici öğretmen', ['Bilgiyi aktaran otorite olarak öğretmen', 'Disiplini sağlayan denetleyici öğretmen', 'Sınav başarısını ölçüp öğrencileri sıralayan değerlendirici öğretmen'], 'Gerekçe her öğrencinin ihtiyacına göre bakım verilmesini vurgular; bu nedenle metafor bireysel gelişimi destekleyen öğretmen kategorisine yerleştirilir.'),
  ('Nitel bir çalışmada birçok kavramın ve kategorinin birbirine nasıl bağlandığını oklarla gösteren görsel düzenlemeye ne ad verilir?', 'Ağ (kavram) gösterimi', ['Histogram', 'Kutu grafiği ve çeyrekler', 'Saçılım diyagramı'], 'Miles ve Huberman\'ın ağ gösterimlerinde düğümler kavramları, oklar ise aralarındaki ilişkileri temsil eder; matrislerle birlikte nitel veri gösteriminin iki ana biçimidir.'),
  ('Uzun süreli bir alan çalışmasında etnografın topluluğun kullandığı yerel sözcükleri ve bunların anlamlarını ayrı bir listede biriktirmesinin çözümlemeye katkısı nedir?', 'Emik kavramların anlamlarını tutarlı biçimde izlemeye ve kültürel alanları belirlemeye yardım etmesi', ['Raporun sayfa sayısını artırarak çalışmanın daha kapsamlı ve titiz görünmesini sağlaması', 'Görüşme yapma gereğini ortadan kaldırması', 'Topluluğun dilini değiştirmeye yardımcı olması'], 'Yerel terimler sözlüğü, bir kültürün kendi kategorilerini görünür kılar ve araştırmacının bu terimleri yanlış yorumlamasını önler.'),
  ('Bir köy etnografisinde araştırmacının hane üyeleri arasındaki kan ve evlilik bağlarını gösteren şemalar çizmesinin temel amacı nedir?', 'Akrabalık ilişkilerinin toplumsal örgütlenmeyi ve dayanışmayı nasıl biçimlendirdiğini görmek', ['Köyün nüfusunu yaş ve cinsiyete göre kesin olarak saymak', 'Köylülerin sağlık durumlarını teşhis etmek', 'Köydeki evlerin mimari planlarını çıkarmak'], 'Akrabalık şemaları klasik antropolojide toplumsal yapıyı anlamanın temel araçlarındandır; miras, evlilik ve iş bölümü gibi ilişkiler bu bağlar üzerinden okunabilir.'),
  ('Bir odak grup oturumunun ses yerine video ile kaydedilmesinin, özellikle döküm aşamasında sağladığı başlıca kolaylık hangisidir?', 'Aynı anda konuşan katılımcıların kim olduğunun belirlenebilmesi', ['Dökümün hiç yapılmasına gerek kalmaması', 'Katılımcıların kayıttan habersiz bırakılabilmesi ve daha doğal davranması', 'Oturum süresinin kendiliğinden kısalması'], 'Ses kaydında benzer sesleri ayırt etmek zordur; görüntü, konuşmacıyı tanımlamayı ve sözel olmayan tepkileri kaydetmeyi kolaylaştırır.'),
  ('Bir program değerlendirmesinde nicel göstergelerin yanında nitel görüşme ve gözlemlerin kullanılması en çok hangi soruyu yanıtlamaya yardım eder?', 'Programın uygulamada nasıl işlediğini ve katılımcıların onu nasıl deneyimlediğini', ['Programa kaç kişinin kayıt yaptırdığını', 'Programın toplam bütçesinin kaç lira olduğunu', 'Katılımcıların sınav puan ortalamasının kaç olduğunu'], 'Nitel veriler programın süreçlerini, beklenmedik sonuçlarını ve katılımcı deneyimini görünür kılar; sayısal göstergeler bunların nedenlerini tek başına açıklayamaz.'),
  ('Nitel çözümlemede bir araştırmacı ortaya çıkan temaları raporlamadan önce "Bu tema araştırma sorumu yanıtlamaya gerçekten katkı sağlıyor mu?" diye soruyor. Bu sorgulamanın amacı nedir?', 'Raporun araştırma sorusuyla ilgili ve odaklı kalmasını sağlamak', ['Tema sayısını her durumda üç ya da dörtle sınırlayıp en aza indirmek', 'Katılımcı sayısını artırmak', 'Verileri sayısallaştırmak'], 'Verideki her ilginç örüntü raporlanmak zorunda değildir; temalar araştırma sorusuna katkıları açısından seçilir ve düzenlenir.'),
  ('Hemşirelerle yapılan görüşmelerde "Vardiya bitse de aklım hastada kalıyor", "Eve gidince uyuyamıyorum" ve "Aileme ayıracak enerjim kalmıyor" ifadeleri tekrar ediyor. Bu ifadeleri kapsayan en uygun tema hangisidir?', 'İşin özel yaşama taşması', ['Hastane binasının fiziksel yetersizliği', 'Hemşirelik eğitiminin müfredatı', 'Ücret politikaları ve maaş artışları'], 'Üç ifade de iş deneyiminin mesai dışındaki zihinsel, bedensel ve ailevi yaşama yayılmasını anlatır; tema bu ortak anlamı yakalar.'),
  ('Odak grup oturumlarının süresi için alan yazında en sık önerilen aralık hangisidir?', 'Yaklaşık 1–2 saat', ['Yaklaşık 5–10 dakika', 'Yaklaşık 6–8 saat', 'Birkaç gün boyunca kesintisiz'], 'Bir ile iki saat arası süre, birkaç anahtar soruyu derinlemesine tartışmaya yeter ve katılımcıları aşırı yormaz.'),
  ('Görüşme dökümlerinde satır numaralarının kullanılmasının çözümleme ve raporlama açısından başlıca yararı nedir?', 'Kodlanan ve alıntılanan parçaların dökümdeki yerinin kolayca bulunup gösterilebilmesi', ['Dökümün daha kısa görünmesini sağlaması', 'Katılımcıların gerçek adlarının gizlenmesini tek başına güvence altına alması', 'Dökümü yazılımın otomatik olarak temalara ve alt temalara ayırmasına olanak vermesi'], 'Satır numaraları, bir alıntının hangi katılımcının hangi bölümünden geldiğini göstermeyi ve denetim izinde veriye geri dönmeyi kolaylaştırır.'),
  ('Klasik antropolojik etnografilerde alan çalışmasının çoğu zaman en az bir yıl sürdürülmesinin önemli gerekçelerinden biri nedir?', 'Mevsimlere bağlı etkinliklerin, törenlerin ve üretim döngülerinin tamamını gözleyebilmek', ['Etik kurul izinlerinin her ülkede yalnızca yıllık olarak verilmesi ve yenilenmemesi', 'Araştırmacının topluluk dilini hiç öğrenmemesi gerektiği', 'Katılımcı sayısının istatistiksel olarak tamamlanması'], 'Tarım, göç, bayram ve düğün gibi etkinlikler yılın farklı zamanlarında yoğunlaşır; bir yıllık döngü topluluğun yaşamının bütününü görmeyi sağlar.'),
  ('Yarı yapılandırılmış bir görüşme formunda çok sayıda (ör. 40) ana soru bulunmasının temel sakıncası nedir?', 'Görüşmenin ankete dönüşmesi ve derinleştirmeye zaman kalmaması', ['Katılımcının daha ayrıntılı ve rahat anlatım yapması', 'Görüşmenin daha esnek, doğal ve sohbet havasında akması', 'Sondaj sorularına daha çok fırsat kalması'], 'Nitel görüşme formları genellikle sınırlı sayıda geniş ana soru içerir; soru sayısı arttıkça her konu yüzeysel kalır.'),
  ('Türkiye\'de nitel araştırma raporlarında ve tezlerde, nicel çalışmalardaki "evren ve örneklem" başlığı yerine sıkça kullanılan ifade hangisidir?', 'Çalışma grubu (katılımcılar)', ['Kontrol grubu', 'Deney grubu', 'Örneklem çerçevesi (liste)'], 'Nitel çalışmalarda istatistiksel temsil amaçlanmadığı için katılımcılar çoğu zaman "çalışma grubu" ya da "katılımcılar" başlığı altında tanıtılır.'),
  ('Bir görüşme dökümünde yalnızca katılımcının yanıtlarının yazılıp görüşmecinin sorularının atlanması neden sorunludur?', 'Yanıtların hangi soruya ve hangi bağlamda verildiği anlaşılamaz; görüşmecinin etkisi de izlenemez', ['Dökümün gereksiz yere uzamasına ve sayfa sayısının artmasına yol açar', 'Katılımcının kimliğini ortaya çıkarır', 'Ses kaydını geçersiz kılar'], 'Görüşme ortak bir üretimdir; soruların biçimi yanıtları etkiler. Bu nedenle dökümde görüşmecinin sözleri de yer almalıdır.'),
  ('Nitel verilerin kodlanması için bir yazılım kullanmak zorunlu mudur?', 'Hayır; kodlama kâğıt, kalem ve renkli işaretleyicilerle elle de yapılabilir', ['Evet; yazılım kullanılmadan yapılan nitel çalışmalar bilimsel dergilerde yayımlanamaz', 'Evet; kodlamayı yalnızca yazılım yapabilir', 'Hayır; çünkü nitel verilerde kodlama yapılmaz'], 'Yazılımlar büyük veri setlerinde işi kolaylaştırır; ancak kodlama bir yorum etkinliğidir ve elle de titizlikle yapılabilir.'),
  ('Nitel araştırma raporlarında araştırmacının "Ben sahaya ilk girdiğimde..." gibi birinci tekil şahısla yazmasının kabul görmesinin temel gerekçesi nedir?', 'Araştırmacının araştırma sürecindeki etkin rolünü ve konumunu şeffaf biçimde göstermesi', ['Akademik yazım ve dil bilgisi kurallarının nitel çalışmalarda hiçbir biçimde geçerli olmaması', 'Raporun daha kısa olmasını sağlaması', 'Katılımcıların sözlerinin rapordan çıkarılmasına olanak vermesi'], 'Nitel gelenekte araştırmacı veriyi üreten ve yorumlayan bir özne olarak görünür kılınır; edilgen dil bu rolü gizleyebilir.'),
  ('Steinar Kvale\'nin görüşmeciler için kullandığı iki benzetmeden "gezgin" benzetmesi hangi görüşme anlayışını anlatır?', 'Bilginin katılımcıyla birlikte yolculuk ederken sohbet içinde kurulduğu anlayışı', ['Bilginin katılımcının zihninde hazır bekleyen bir maden gibi çıkarıldığı anlayışı', 'Görüşmecinin soruları hiçbir değişiklik yapmadan okuduğu anlayışı', 'Görüşmenin yalnızca kapalı uçlu sorulardan oluştuğu anlayışı'], 'Kvale\'ye göre "madenci" görüşmeci hazır bilgiyi çıkarmaya çalışır; "gezgin" görüşmeci ise katılımcıyla konuşarak birlikte anlam üretir ve dönüşerek döner.'),
  ('Holstein ve Gubrium\'un "etkin görüşme" (active interview) kavramı neyi vurgular?', 'Görüşmenin, görüşmeci ve katılımcının anlamı birlikte kurduğu etkileşimli bir süreç olduğunu', ['Görüşmecinin hiçbir soru sormadan ve hiçbir tepki göstermeden yalnızca sessizce dinlemesi gerektiğini', 'Katılımcının yanıtlarının önceden hazırlanmış olması gerektiğini', 'Görüşmenin yalnızca bedensel etkinlik sırasında yapılması gerektiğini'], 'Holstein ve Gubrium, katılımcıyı yanıtları hazır bir "kap" olarak görmez; yanıtların görüşmenin etkileşimi içinde üretildiğini ve bunun da çözümlenmesi gerektiğini savunur.'),
  ('Nitel araştırmada "şeffaflık" ilkesi en iyi hangi uygulamayla karşılanır?', 'Veri toplama, kodlama ve yorum kararlarının raporda açıkça anlatılması', ['Katılımcıların kimliklerinin raporda açıkça yazılması', 'Bulguların yalnızca kısa bir özet halinde verilip yöntemin ve sürecin hiç anlatılmaması', 'Ham verilerin çözümlemeden sonra imha edilmesi'], 'Şeffaflık, okurun araştırmanın nasıl yapıldığını izleyip değerlendirebilmesi için yöntemsel kararların açıklanmasıdır; kimliklerin açıklanmasıyla karıştırılmamalıdır.'),
  ('Bir görüşmeci katılımcı anlatırken sık sık sözünü kesip yeni sorular soruyor. Bu davranışın veriye en olası etkisi nedir?', 'Katılımcının anlatısının bölünmesi ve giderek daha kısa yanıtlar vermesi', ['Katılımcının giderek daha uzun, daha rahat ve daha ayrıntılı anlatımlar yapması', 'Görüşmenin daha doğal bir sohbete dönüşmesi', 'Dökümün daha kolay yapılması'], 'Sürekli kesilen katılımcı, düşüncesini tamamlayamayacağını düşünerek kısa yanıtlarla yetinebilir; görüşmeci anlatının akmasına izin vermelidir.'),
  ('Köydeki yaşlı kadınlarla görüşme yapan bir araştırmacının "toplumsal cinsiyet rollerinin içselleştirilmesi" gibi akademik terimler yerine "Kızken evde hangi işleri yapardınız?" gibi sorular sorması neden önemlidir?', 'Soruların katılımcının gündelik diline uygun ve anlaşılır olmasını sağlamak', ['Katılımcının konuyu hiç anlamamasını sağlamak', 'Görüşmeyi daha resmî ve mesafeli kılmak', 'Akademik kavramların görüşmede de, araştırma raporunda da kullanılmasını tamamen yasaklamak'], 'Nitel görüşmelerde sorular katılımcının dilinde sorulur; akademik kavramlar çözümleme aşamasında araştırmacı tarafından kullanılır.'),
  ('Nitel bir raporda görüşme sayısının yanında görüşmelerin ortalama ve toplam süresinin de belirtilmesinin okura sağladığı bilgi nedir?', 'Toplanan verinin miktarı ve derinliği hakkında bir fikir edinmesi', ['Bulguların istatistiksel anlamlılığını ve güven aralığını kendi başına hesaplayabilmesi', 'Katılımcıların kimliklerini belirlemesi', 'Görüşmelerin hangi dilde yapıldığını öğrenmesi'], 'Süre bilgisi, örneğin 12 görüşmenin 20\'şer dakika mı yoksa 90\'ar dakika mı sürdüğünü göstererek verinin zenginliğini değerlendirmeye yardım eder.'),
  ('Görüşme sırasında masaya konan büyük bir kayıt cihazının katılımcıyı tedirgin ettiği fark ediliyor. Görüşmecinin en uygun davranışı hangisidir?', 'Kaydın amacını kısaca hatırlatıp cihazı göze batmayan bir yere koymak ve sohbete odaklanmak', ['Katılımcıya haber vermeden cihazı gizlice çalıştırmaya devam edip görüşmeyi olağan biçimde sürdürmek', 'Katılımcıya tedirginliğinin araştırmayı bozduğunu söylemek', 'Görüşmeyi hemen sonlandırıp katılımcıyı çalışmadan çıkarmak'], 'Kayıt cihazı bazı katılımcıları başlangıçta gerebilir; açıklama yapmak ve dikkati cihazdan sohbete çekmek genellikle bu etkiyi azaltır.'),
  ('Bir gazetecinin haber için yaptığı röportaj ile nitel araştırmadaki derinlemesine görüşme arasındaki temel fark hangisidir?', 'Nitel görüşmenin bir araştırma sorusuna bağlı, sistemli örneklem ve çözümleme süreciyle yürütülmesi', ['Röportajın her zaman daha uzun sürmesi, daha çok soru içermesi ve kayıt altına alınması', 'Nitel görüşmede hiçbir zaman soru sorulmaması', 'Röportajın yalnızca yazılı, nitel görüşmenin yalnızca sözlü olması'], 'Her ikisi de soru sormaya dayanır; ancak nitel görüşme katılımcı seçimi, kayıt, döküm, kodlama ve gizlilik gibi araştırma süreçlerinin parçasıdır.'),
  ('Odak grup görüşmelerinde katılımcıların genellikle yuvarlak ya da U biçimli bir masa çevresinde oturtulmasının amacı nedir?', 'Katılımcıların birbirini görerek doğrudan etkileşime girmesini kolaylaştırmak', ['Katılımcıların birbirini görmesini engellemek', 'Moderatörün katılımcıları başarılarına göre sıralayıp not vermesini sağlamak', 'Kayıt cihazına gerek kalmamasını sağlamak'], 'Odak grubun değeri katılımcılar arası etkileşimden gelir; yüz yüze oturma düzeni bu etkileşimi destekler.'),
  ('Pazar araştırmalarında odak grupların sıklıkla tek yönlü aynalı bir gözlem odası bulunan salonlarda yapılmasının amacı nedir?', 'Müşteri temsilcilerinin tartışmayı katılımcıları etkilemeden izleyebilmesi', ['Katılımcıların moderatörü ve birbirlerini hiç görmeden yalnızca sesle tartışabilmesi', 'Oturumun ses kaydına gerek kalmaması', 'Katılımcı sayısının istatistiksel olarak artırılması'], 'Gözlem odası, araştırmayı sipariş eden ekibin tartışmayı canlı izlemesini sağlar; katılımcılara izlendiklerinin bildirilmesi ise etik bir gerekliliktir.'),
  ('Bir saatlik bir görüşmenin kelimesi kelimesine yazıya geçirilmesi için gereken süre konusunda hangisi genellikle doğrudur?', 'Döküm, görüşmenin kendisinden çok daha uzun sürer', ['Döküm, görüşme süresinin yarısında tamamlanır', 'Döküm her zaman tam olarak görüşme süresi kadar sürer', 'Döküm için ses kaydını dinlemeye gerek yoktur'], 'Konuşmayı durdurup yeniden dinleyerek yazmak zaman alır; bu nedenle nitel çalışmalarda döküm için ayrılacak süre ve kaynak önceden planlanmalıdır.'),
  ('Bir araştırmacı gözlem yapacağı köy okuluna veri toplamaya başlamadan önce bir kez gidip ortamı tanıyor, öğretmenlerle tanışıyor ve gözlem için uygun saatleri öğreniyor. Bu ön ziyaretin amacı nedir?', 'Sahayı tanıyıp veri toplama planını gerçekçi biçimde düzenlemek', ['Çalışmanın bütün verilerini bu ziyarette toplamak', 'Okulun öğretmenlerini değerlendirip puanlamak', 'Gözlemi tamamen gereksiz hale getirmek'], 'Keşif ziyaretleri erişim, zamanlama ve mekân gibi pratik konuları netleştirir; ayrıca ilk tanışmayla güven ilişkisinin temeli atılır.'),
  ('Görüşme yapılacak kişiye önceden görüşmenin yaklaşık ne kadar süreceğinin bildirilmesinin yararı nedir?', 'Katılımcının yeterli zaman ayırıp görüşmeye acele etmeden katılabilmesi', ['Görüşmenin her durumda daha kısa sürmesinin sağlanması', 'Katılımcının soruları önceden ezberlemesi', 'Ses kaydına gerek kalmaması'], 'Süre bilgisini bilen katılımcı programını buna göre ayarlar; görüşmenin ortasında acele etmesi ya da ayrılmak zorunda kalması önlenir.'),
  ('Katılımcı sayısının 4–6 kişiyle sınırlı tutulduğu "mini odak grup" hangi durumda klasik odak gruba tercih edilebilir?', 'Katılımcıların konuya ilişkin derin uzmanlığı ya da deneyimi olduğunda ve her birinden ayrıntılı katkı istendiğinde', ['Araştırmacının yalnızca hızlı bir oylama sonucu elde etmek ve tartışmayı kısa tutmak istediğinde', 'Katılımcıların birbiriyle hiç konuşmaması istendiğinde', 'Bulguların istatistiksel olarak genellenmesi gerektiğinde'], 'Küçük gruplarda her katılımcıya daha fazla konuşma süresi düşer; bu, uzmanlarla ya da yoğun deneyim sahipleriyle yapılan tartışmalarda avantaj sağlar.'),
  ('Odak grup görüşmelerinin bireysel görüşmelere göre pratik bir üstünlüğü hangisidir?', 'Görece kısa sürede birden çok kişiden aynı anda veri toplanabilmesi', ['Her katılımcının yaşam öyküsünün ayrıntılı biçimde alınabilmesi', 'Katılımcıların gizliliğinin ve anonimliğinin tümüyle ve kesin olarak güvence altında olması', 'Bulguların evrene istatistiksel olarak genellenebilmesi'], 'Bir oturumda altı ile on kişinin görüşü alınabilir; ancak her bireyden derinlemesine kişisel anlatı almak bireysel görüşmeye göre daha zordur.'),
  ('Birden fazla kişinin döküm yaptığı bir projede ortak bir "döküm kılavuzu" (ör. duraksamaların, anlaşılmayan bölümlerin ve kesilmelerin nasıl gösterileceği) hazırlanmasının amacı nedir?', 'Dökümlerin tutarlı biçimde hazırlanıp karşılaştırılabilir olmasını sağlamak', ['Dökümlerin farklı dillerde yazılmasını zorunlu kılmak', 'Ses kayıtlarının silinmesine olanak vermek', 'Dökümcülerin kendi yorumlarını ve tahminlerini metne serbestçe ekleyebilmesini sağlamak'], 'Ortak kurallar olmadan aynı tür olay farklı dökümlerde farklı gösterilir; bu durum çözümlemeyi ve karşılaştırmayı zorlaştırır.'),
  ('Odak grup oturumlarında katılımcıların önüne yalnızca ön adlarının yazılı olduğu isim kartları konmasının amacı nedir?', 'Moderatörün ve katılımcıların birbirine adıyla hitap edebilmesi, böylece etkileşimin kolaylaşması', ['Katılımcıların tam ad, soyad ve kurum bilgilerinin kayıtlarda ve dökümlerde açıkça görünmesi', 'Katılımcıların oturum boyunca hiç konuşmaması', 'Katılımcıların sınav puanlarının gösterilmesi'], 'Adla hitap, sessiz katılımcıları tartışmaya davet etmeyi ve dökümde konuşmacıları ayırt etmeyi kolaylaştırır; yalnızca ön adın kullanılması mahremiyeti de gözetir.'),
];
